import{_ as d,o as a,c as r,a0 as e}from"./chunks/framework.DzvPB4Y-.js";const b=JSON.parse('{"title":"从业务场景选择框架","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/index.md","filePath":"zh-cn/frameworks/index.md"}'),h={name:"zh-cn/frameworks/index.md"};function o(i,t,l,n,s,c){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="从业务场景选择框架" tabindex="-1">从业务场景选择框架 <a class="header-anchor" href="#从业务场景选择框架" aria-label="Permalink to &quot;从业务场景选择框架&quot;">​</a></h1><p>业务框架把可复用的领域模型、约束、候选生成和求解流程组合起来。你提供业务数据、选择目标并接入求解器，不必从决策变量开始重写整个模型。</p><p>这条学习路线与<a href="/ospf/zh-cn/guide/getting-started.html">从 Core 开始建模</a>并行：已有合适的领域框架时先复用；问题超出框架范围时，再组合多个业务框架，或退回 Core 层自行建模。不要求先读完领域驱动设计（DDD）或列生成理论。</p><h2 id="我的问题该选哪一个" tabindex="-1">我的问题该选哪一个？ <a class="header-anchor" href="#我的问题该选哪一个" aria-label="Permalink to &quot;我的问题该选哪一个？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你需要做出的决策</th><th>框架</th><th>第一课</th></tr></thead><tbody><tr><td>已有长条物品如何放进有限长度的容器（如型材定尺装载）</td><td><a href="./bpp1d/">一维装箱 BPP1D</a></td><td><a href="./bpp1d/first-packing.html">第一次一维装箱：物品、间距与库存</a></td></tr><tr><td>已有二维物品如何排到有限板面上（如托盘码放）</td><td><a href="./bpp2d/">二维装箱 BPP2D</a></td><td><a href="./bpp2d/first-layout.html">第一次二维排样：矩形排样与结果检查</a></td></tr><tr><td>货物如何装入箱体或集装箱（如集装箱拼箱）</td><td><a href="./bpp3d/">三维装箱 BPP3D</a></td><td><a href="./bpp3d/first-loading.html">第一次三维装箱：从长方体装载开始</a></td></tr><tr><td>原料如何分切以满足不同宽度的订单（如钢卷/薄膜分切）</td><td><a href="./csp1d/">一维分切 CSP1D</a></td><td><a href="./csp1d/first-slitting.html">第一次卷材分切：产品需求与切割方案</a></td></tr><tr><td>定尺板材或卷材如何裁成矩形产品（如板材/玻璃开料）</td><td><a href="./csp2d/">二维套裁 CSP2D</a></td><td><a href="./csp2d/first-cutting.html">第一次板材套裁：板材、图案与生产数量</a></td></tr><tr><td>活动何时执行，同时占用哪些资源（如机台排产）</td><td><a href="./gantt/">时间与资源排程 Gantt</a></td><td><a href="./gantt/first-schedule.html">第一次活动排程：有限候选活动排程</a></td></tr><tr><td>供需、流量、路径和网络建设如何配置（如供应链调拨）</td><td><a href="./network/">网络优化 Network</a></td><td><a href="./network/first-flow.html">第一次网络流优化：先解决一个小型流问题</a></td></tr></tbody></table><h2 id="容易选错的两个地方" tabindex="-1">容易选错的两个地方 <a class="header-anchor" href="#容易选错的两个地方" aria-label="Permalink to &quot;容易选错的两个地方&quot;">​</a></h2><h3 id="装箱与下料-看业务语义-不只看维数" tabindex="-1">装箱与下料：看业务语义，不只看维数 <a class="header-anchor" href="#装箱与下料-看业务语义-不只看维数" aria-label="Permalink to &quot;装箱与下料：看业务语义，不只看维数&quot;">​</a></h3><ul><li><strong>问“图案复用几次、生产多少量、是否允许超产”选 CSP</strong>：关注原料加工、产品需求、方案产出和设备工艺。</li><li><strong>问“放进哪个箱、什么坐标和朝向”选 BPP</strong>：关注已有物品的放置与装载。</li><li>按业务语义核对边界：BPP2D 也支持间距、刀缝和余料报告；CSP2D 的定尺模式也具有二维装箱结构。“有没有刀缝”不能单独决定选型。</li></ul><h3 id="gantt-与-network-时间安排和网络决策可以组合" tabindex="-1">Gantt 与 Network：时间安排和网络决策可以组合 <a class="header-anchor" href="#gantt-与-network-时间安排和网络决策可以组合" aria-label="Permalink to &quot;Gantt 与 Network：时间安排和网络决策可以组合&quot;">​</a></h3><ul><li><strong>问“活动何时执行、占用哪些资源”选 Gantt</strong>：负责活动、资源、依赖和日历。</li><li><strong>问“流经哪些弧、沿什么路径、如何建设网络”选 Network</strong>：负责拓扑、流、资源路径和结构。</li><li>需要时再组合：维修人员排程可将 Gantt 与 Network 路径子问题组合；车辆路径是 Network 的进阶入口。</li></ul><h2 id="建议的学习顺序" tabindex="-1">建议的学习顺序 <a class="header-anchor" href="#建议的学习顺序" aria-label="Permalink to &quot;建议的学习顺序&quot;">​</a></h2><ol><li>阅读<a href="./setup.html">环境与运行方式</a>，添加领域依赖并选择实际后端或明确的默认启发式。</li><li>选择一个框架，先看其输入、输出和不适用范围。</li><li>把第一课的示例函数和启动入口放进小型应用，学习构造输入、调用框架和读取结果。</li><li>完成教程末尾的一个业务变更练习，同时修改相应验收条件。</li><li>阅读<a href="./integration.html">接入自己的业务</a>，再进入对应框架的第二课，把需求、目标和规则替换成自己的数据。</li><li>需要跨领域组合时，再阅读<a href="/ospf/zh-cn/examples/framework-examples.html">综合案例</a>或<a href="/ospf/zh-cn/guide/use-ddd-architecture.html">领域驱动设计</a>。</li></ol><h2 id="跑通之后-接着学什么" tabindex="-1">跑通之后，接着学什么？ <a class="header-anchor" href="#跑通之后-接着学什么" aria-label="Permalink to &quot;跑通之后，接着学什么？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>框架</th><th>第二课</th><th>要能回答的问题</th></tr></thead><tbody><tr><td>一维装箱 BPP1D</td><td><a href="./bpp1d/business-scenario.html">多容器类型、库存与费用</a></td><td>为什么最少容器数与最小费用会选不同容器类型？</td></tr><tr><td>二维装箱 BPP2D</td><td><a href="./bpp2d/business-scenario.html">多板型、旋转与间距</a></td><td>面积够用，为什么仍可能排不下？</td></tr><tr><td>三维装箱 BPP3D</td><td><a href="./bpp3d/business-scenario.html">多箱型与目标配置</a></td><td>默认体积目标和业务费用如何权衡？</td></tr><tr><td>一维分切 CSP1D</td><td><a href="./csp1d/business-scenario.html">需求计量与业务规则</a></td><td>卷数、重量与方案使用次数怎样对应？</td></tr><tr><td>二维套裁 CSP2D</td><td><a href="./csp2d/business-scenario.html">刀缝、工艺与卷材</a></td><td>图案可放，为什么仍不一定可加工？</td></tr><tr><td>时间与资源排程 Gantt</td><td><a href="./gantt/business-scenario.html">停机日历与滚动重排</a></td><td>已实际执行记录、冻结与可调整基准排程有何区别？</td></tr><tr><td>网络优化 Network</td><td><a href="./network/business-scenario.html">共享资源、缺货与联合模型</a></td><td>弧容量充分，为什么仍可能无法交付？</td></tr></tbody></table><p>第二课提供场景输入和业务规则示例，并说明需要应用自行实现的部分。将手算结果作为业务对照，并结合程序返回的报告判断求解范围。</p><h2 id="怎样判断自己真的学会了" tabindex="-1">怎样判断自己真的学会了？ <a class="header-anchor" href="#怎样判断自己真的学会了" aria-label="Permalink to &quot;怎样判断自己真的学会了？&quot;">​</a></h2><p>不以“程序返回成功”为唯一标准。你应能解释：输入的数量和单位是什么、哪些规则是硬约束、优化的是什么、结果是否满足需求，以及结果证明到什么范围。</p><table tabindex="0"><thead><tr><th>观察到的结果</th><th>可以得出的结论</th><th>不能直接得出的结论</th></tr></thead><tbody><tr><td>输入校验或模型注册通过</td><td>数据或模型配置通过对应检查</td><td>已求解、已有可行方案</td></tr><tr><td>模拟回调返回预设解</td><td>求解调用与结果解析在该测试数据下工作正常</td><td>原生求解器找到该解</td></tr><tr><td>独立枚举验证小实例</td><td>对所枚举的有限问题成立</td><td>任意规模和连续模型都成立</td></tr><tr><td>最终 MILP 返回整数方案</td><td>需继续复核业务可行性与报告</td><td>完整业务问题已证明最优</td></tr><tr><td>当前候选集合对应的模型被证明最优</td><td>在这些候选方案中已找到最优选择</td><td>未生成的方案也不可能改进</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Kotlin 与 Rust 的接口差异</p><p>Kotlin 与 Rust 共用业务解释，但接口与已完成能力并不完全相同。每课列出各自的入口与结果含义；数值复核以该语言的具体示例为准。</p></div><h2 id="terminology" tabindex="-1">术语与阅读约定 <a class="header-anchor" href="#terminology" aria-label="Permalink to &quot;术语与阅读约定 {#terminology}&quot;">​</a></h2><p>同一领域使用固定称呼：BPP1D 用“容器／容器类型”，BPP2D 用“板材／板型”，BPP3D 用“箱体／箱型”；CSP1D 的“切割方案”包含单次产出，CSP2D 的“切割图案”描述一次加工的排布。正文统一用“费用”描述 <code>cost</code>；代码中的类名、字段名和参数名保留 API 原名。</p><table tabindex="0"><thead><tr><th>术语</th><th>在教程中的含义</th></tr></thead><tbody><tr><td>候选方案、列</td><td>候选方案是可以选用的装载或加工组合；在列生成模型中，通常用一个变量及其在约束和目标中的系数表示一个候选方案</td></tr><tr><td>主问题、受限主问题（<code>RMP</code>）</td><td>主问题决定选择哪些候选及其使用次数；受限主问题只考虑当前已生成的候选，在列生成过程中通常先求解其线性松弛模型</td></tr><tr><td>线性规划（LP）、混合整数线性规划（MILP）</td><td>LP 允许连续变量；MILP 要求部分或全部变量取整数。线性松弛允许原来的整数变量暂时取小数，用于估计目标界限和指导候选搜索</td></tr><tr><td>列生成、定价</td><td>列生成逐轮加入候选；“定价”是利用主问题反馈搜索可改进目标的候选，不是设置商品售价。具体接口是否使用精确算法，以各课说明为准</td></tr><tr><td>求解后端、适配器</td><td>后端负责执行求解，例如 SCIP、Gurobi；适配器把框架的模型、配置和结果转换到后端接口</td></tr><tr><td>模型注册</td><td>将领域对象对应的变量、约束和目标加入求解模型</td></tr><tr><td>启发式求解</td><td>按规则寻找方案，通常不提供完整问题的最优性证明；仍需检查结果是否满足业务要求</td></tr><tr><td>当前可行解（<code>incumbent</code>）</td><td>求解器目前找到的可行解，不一定最优，交给业务系统前仍需复核</td></tr><tr><td>候选完整性（<code>complete</code>）</td><td>是否已枚举完当前规则下的全部候选，不等于已经证明整数最优</td></tr><tr><td>目标界限、最优性差距</td><td>用于判断当前解离已知最优界限还有多远；后端未提供时应标记为“未提供”</td></tr><tr><td>结果指标（KPI）</td><td>箱数、利用率、费用、欠产等业务统计，具体字段随框架和语言而不同</td></tr></tbody></table>',22)])])}const p=d(h,[["render",o]]);export{b as __pageData,p as default};
